package main

import (
	"bufio"
	"fmt"
	"os"
)

type InputReader struct {
	scanner *bufio.Scanner
}

func NewInputReader() *InputReader {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return &InputReader{scanner: sc}
}

func (ir *InputReader) readInt() int {
	if !ir.scanner.Scan() {
		return 0
	}
	var x int
	fmt.Sscan(ir.scanner.Text(), &x)
	return x
}

type Utils struct{}

func ntimes(n int, f func() interface{}, returnResults bool) map[int]interface{} {
	a := make(map[int]interface{})
	for i := 1; i <= n; i++ {
		result := f()
		if returnResults {
			a[i] = result
		}
	}
	return a
}

func cumsum(a map[int]int) {
	sum := 0
	for k := range a {
		a[k] += sum
		sum = a[k]
	}
}

func diff(a map[int]int) {
	prev := 0
	for k := range a {
		buf := a[k]
		a[k] -= prev
		prev = buf
	}
}

func bitCount(n int) int {
	cnt := 0
	for j := n; j != 0; j >>= 1 {
		cnt += j & 1
	}
	return cnt
}

type PrimeUtils struct{}

var divisorsCache = map[int]map[int]bool{
	1: {1: true},
	2: {1: true, 2: true},
}
var primesCache = map[int]int{}

func primes(limit int) []int {
	size := (limit >> 3) + 1
	a := make([]byte, size)
	for i := range a {
		a[i] = 85
	}
	a[0] = 83
	for i := 3; i*i < limit; i += 2 {
		if (a[i>>3] & (1 << (uint(i) % 8))) != 0 {
			continue
		}
		for k := i; k*i < limit; k++ {
			n := k * i
			a[n>>3] |= 1 << (uint(n) % 8)
		}
	}
	res := []int{2}
	for i := 3; i < limit; i += 2 {
		if (a[i>>3] & (1 << (uint(i) % 8))) == 0 {
			res = append(res, i)
		}
	}
	return res
}

func divisors(n int, lp int) map[int]bool {
	if d, ok := divisorsCache[n]; ok {
		return d
	}
	if len(primesCache) == 0 {
		ps := primes(1000)
		for _, p := range ps {
			primesCache[p] = p
		}
	}
	r := map[int]bool{}
	for p := range primesCache {
		if p >= lp {
			if n < p*p {
				r[1] = true
				r[n] = true
				break
			} else if n%p == 0 {
				for _, pre := range []int{1, p} {
					sub := divisors(n/p, p)
					for nxt := range sub {
						r[nxt*pre] = true
					}
				}
				break
			}
		}
	}
	divisorsCache[n] = r
	return r
}

