	ir := NewInputReader()
	n := ir.readInt()
	k := ir.readInt()

	xs := []int{}
	for divisor := range divisors(n, 2) {
		l := divisor
		m := n / l
		if m < k {
			xs = append(xs, k*l+m)
		}
	}

	if len(xs) == 0 {
		fmt.Print(n*k + 1)
	} else {
		min := xs[0]
		for _, v := range xs {
			if v < min {
				min = v
			}
		}
		fmt.Print(min)
	}
}

